USE [GymApp]
GO

-- ============================================================
-- Traducciones del asistente de alta de Alumnos.aspx (edad,
-- búsqueda por DNI, tutor/familiar, credenciales generadas)
-- ============================================================
ALTER TABLE [Traducciones].[Pantalla_Alumnos]
    ADD [alumnos_asistente_titulo_tutor]           NVARCHAR(500) NOT NULL DEFAULT N'',
        [alumnos_asistente_msg_tutor]               NVARCHAR(500) NOT NULL DEFAULT N'',
        [alumnos_asistente_titulo_tutor_dni]        NVARCHAR(500) NOT NULL DEFAULT N'',
        [alumnos_asistente_titulo_vincular]         NVARCHAR(500) NOT NULL DEFAULT N'',
        [alumnos_asistente_titulo_confirmar]        NVARCHAR(500) NOT NULL DEFAULT N'',
        [alumnos_asistente_titulo_datos]            NVARCHAR(500) NOT NULL DEFAULT N'',
        [alumnos_asistente_titulo_datos_familiar]   NVARCHAR(500) NOT NULL DEFAULT N'',
        [alumnos_asistente_confirmar_alumno_fmt]    NVARCHAR(500) NOT NULL DEFAULT N'',
        [alumnos_asistente_confirmar_vinculo_fmt]   NVARCHAR(500) NOT NULL DEFAULT N'',
        [alumnos_asistente_error_mismo_dni]         NVARCHAR(500) NOT NULL DEFAULT N'',
        [alumnos_asistente_error_tutor_menor]       NVARCHAR(500) NOT NULL DEFAULT N'',
        [alumnos_asistente_error_usuario_existe]    NVARCHAR(500) NOT NULL DEFAULT N'',
        [alumnos_asistente_lbl_dni_familiar]        NVARCHAR(500) NOT NULL DEFAULT N'',
        [alumnos_asistente_lbl_parentesco]          NVARCHAR(500) NOT NULL DEFAULT N'',
        [alumnos_asistente_lbl_usuario]              NVARCHAR(500) NOT NULL DEFAULT N'',
        [alumnos_asistente_lbl_contrasena]          NVARCHAR(500) NOT NULL DEFAULT N'',
        [alumnos_asistente_hint_contrasena]         NVARCHAR(500) NOT NULL DEFAULT N'',
        [alumnos_asistente_btn_si]                  NVARCHAR(500) NOT NULL DEFAULT N'',
        [alumnos_asistente_btn_no]                  NVARCHAR(500) NOT NULL DEFAULT N'',
        [alumnos_asistente_btn_buscar]               NVARCHAR(500) NOT NULL DEFAULT N'',
        [alumnos_asistente_btn_confirmar]           NVARCHAR(500) NOT NULL DEFAULT N'',
        [alumnos_credenciales_titulo]               NVARCHAR(500) NOT NULL DEFAULT N'',
        [alumnos_credenciales_aviso]                NVARCHAR(500) NOT NULL DEFAULT N'',
        [alumnos_msg_familiar_vinculado]            NVARCHAR(500) NOT NULL DEFAULT N'',
        [alumnos_msg_familiar_desvinculado]         NVARCHAR(500) NOT NULL DEFAULT N'',
        [alumnos_rol_titular]                       NVARCHAR(500) NOT NULL DEFAULT N'',
        [alumnos_rol_familiar]                      NVARCHAR(500) NOT NULL DEFAULT N'',
        [alumnos_lbl_familiares]                    NVARCHAR(500) NOT NULL DEFAULT N'',
        [alumnos_familiares_vacio]                  NVARCHAR(500) NOT NULL DEFAULT N'';
GO

UPDATE [Traducciones].[Pantalla_Alumnos] SET
    [alumnos_asistente_titulo_tutor]         = CASE [IdiomaID] WHEN 1 THEN N'¿Asociar con un familiar?'                                  WHEN 2 THEN N'Link to a family member?'                              WHEN 3 THEN N'Associar a um familiar?'                                WHEN 4 THEN N'Associer à un membre de la famille ?'                    WHEN 5 THEN N'家族に関連付けますか？' END,
    [alumnos_asistente_msg_tutor]            = CASE [IdiomaID] WHEN 1 THEN N'Esta persona es menor de edad. ¿Querés asociarla a la cuenta de un familiar (madre, padre o tutor)?' WHEN 2 THEN N'This person is a minor. Do you want to link them to a family member''s account (mother, father or guardian)?' WHEN 3 THEN N'Esta pessoa é menor de idade. Deseja associá-la à conta de um familiar (mãe, pai ou responsável)?' WHEN 4 THEN N'Cette personne est mineure. Voulez-vous l''associer au compte d''un membre de la famille (mère, père ou tuteur) ?' WHEN 5 THEN N'この方は未成年です。家族（母、父、または保護者）のアカウントに関連付けますか？' END,
    [alumnos_asistente_titulo_tutor_dni]     = CASE [IdiomaID] WHEN 1 THEN N'Datos del familiar'                                          WHEN 2 THEN N'Family member details'                                  WHEN 3 THEN N'Dados do familiar'                                      WHEN 4 THEN N'Données du membre de la famille'                          WHEN 5 THEN N'家族の情報' END,
    [alumnos_asistente_titulo_vincular]      = CASE [IdiomaID] WHEN 1 THEN N'Vincular familiar'                                            WHEN 2 THEN N'Link family member'                                     WHEN 3 THEN N'Vincular familiar'                                       WHEN 4 THEN N'Lier un membre de la famille'                              WHEN 5 THEN N'家族を関連付ける' END,
    [alumnos_asistente_titulo_confirmar]     = CASE [IdiomaID] WHEN 1 THEN N'Confirmar'                                                   WHEN 2 THEN N'Confirm'                                                WHEN 3 THEN N'Confirmar'                                              WHEN 4 THEN N'Confirmer'                                                WHEN 5 THEN N'確認' END,
    [alumnos_asistente_titulo_datos]         = CASE [IdiomaID] WHEN 1 THEN N'Completar datos del Alumno'                                  WHEN 2 THEN N'Complete the Student''s details'                        WHEN 3 THEN N'Completar dados do Aluno'                                WHEN 4 THEN N'Compléter les données de l''élève'                        WHEN 5 THEN N'生徒の情報を入力' END,
    [alumnos_asistente_titulo_datos_familiar]= CASE [IdiomaID] WHEN 1 THEN N'Completar datos del familiar'                                WHEN 2 THEN N'Complete the family member''s details'                   WHEN 3 THEN N'Completar dados do familiar'                             WHEN 4 THEN N'Compléter les données du membre de la famille'            WHEN 5 THEN N'家族の情報を入力' END,
    [alumnos_asistente_confirmar_alumno_fmt] = CASE [IdiomaID] WHEN 1 THEN N'{0}, {1} (DNI {2} - {3}) ya está registrado en el sistema. ¿Querés asociarlo también como Alumno?' WHEN 2 THEN N'{0}, {1} (ID {2} - {3}) is already registered in the system. Do you also want to add them as a Student?' WHEN 3 THEN N'{0}, {1} (CPF {2} - {3}) já está registrado no sistema. Deseja também associá-lo como Aluno?' WHEN 4 THEN N'{0}, {1} (ID {2} - {3}) est déjà enregistré dans le système. Voulez-vous aussi l''ajouter comme élève ?' WHEN 5 THEN N'{0} {1}（ID {2} - {3}）は既にシステムに登録されています。生徒としても関連付けますか？' END,
    [alumnos_asistente_confirmar_vinculo_fmt]= CASE [IdiomaID] WHEN 1 THEN N'{0}, {1} (DNI {2}) ya está registrado en el sistema. ¿Confirmás el vínculo?' WHEN 2 THEN N'{0}, {1} (ID {2}) is already registered in the system. Confirm the link?' WHEN 3 THEN N'{0}, {1} (CPF {2}) já está registrado no sistema. Confirma o vínculo?' WHEN 4 THEN N'{0}, {1} (ID {2}) est déjà enregistré dans le système. Confirmer le lien ?' WHEN 5 THEN N'{0} {1}（ID {2}）は既にシステムに登録されています。関連付けを確認しますか？' END,
    [alumnos_asistente_error_mismo_dni]      = CASE [IdiomaID] WHEN 1 THEN N'El familiar no puede tener el mismo DNI que el alumno'      WHEN 2 THEN N'The family member cannot have the same ID as the student' WHEN 3 THEN N'O familiar não pode ter o mesmo CPF do aluno'             WHEN 4 THEN N'Le membre de la famille ne peut pas avoir le même ID que l''élève' WHEN 5 THEN N'家族は生徒と同じIDを持つことはできません' END,
    [alumnos_asistente_error_tutor_menor]    = CASE [IdiomaID] WHEN 1 THEN N'El familiar debe ser mayor de edad'                          WHEN 2 THEN N'The family member must be of legal age'                  WHEN 3 THEN N'O familiar deve ser maior de idade'                       WHEN 4 THEN N'Le membre de la famille doit être majeur'                   WHEN 5 THEN N'家族は成人である必要があります' END,
    [alumnos_asistente_error_usuario_existe] = CASE [IdiomaID] WHEN 1 THEN N'Ese nombre de usuario ya existe. Elegí otro.'                WHEN 2 THEN N'That username already exists. Choose another one.'         WHEN 3 THEN N'Esse nome de usuário já existe. Escolha outro.'            WHEN 4 THEN N'Ce nom d''utilisateur existe déjà. Choisissez-en un autre.' WHEN 5 THEN N'そのユーザー名は既に存在します。別の名前を選んでください。' END,
    [alumnos_asistente_lbl_dni_familiar]     = CASE [IdiomaID] WHEN 1 THEN N'DNI del familiar'                                            WHEN 2 THEN N'Family member''s ID'                                     WHEN 3 THEN N'CPF do familiar'                                        WHEN 4 THEN N'ID du membre de la famille'                                WHEN 5 THEN N'家族のID' END,
    [alumnos_asistente_lbl_parentesco]       = CASE [IdiomaID] WHEN 1 THEN N'Parentesco'                                                  WHEN 2 THEN N'Relationship'                                           WHEN 3 THEN N'Parentesco'                                             WHEN 4 THEN N'Lien de parenté'                                          WHEN 5 THEN N'続柄' END,
    [alumnos_asistente_lbl_usuario]          = CASE [IdiomaID] WHEN 1 THEN N'Usuario'                                                     WHEN 2 THEN N'Username'                                               WHEN 3 THEN N'Usuário'                                                WHEN 4 THEN N'Nom d''utilisateur'                                       WHEN 5 THEN N'ユーザー名' END,
    [alumnos_asistente_lbl_contrasena]       = CASE [IdiomaID] WHEN 1 THEN N'Contraseña (opcional)'                                       WHEN 2 THEN N'Password (optional)'                                    WHEN 3 THEN N'Senha (opcional)'                                       WHEN 4 THEN N'Mot de passe (facultatif)'                                WHEN 5 THEN N'パスワード（任意）' END,
    [alumnos_asistente_hint_contrasena]      = CASE [IdiomaID] WHEN 1 THEN N'Si se deja vacío, se genera una contraseña segura automáticamente' WHEN 2 THEN N'If left empty, a secure password is generated automatically' WHEN 3 THEN N'Se deixado em branco, uma senha segura é gerada automaticamente' WHEN 4 THEN N'Si laissé vide, un mot de passe sécurisé est généré automatiquement' WHEN 5 THEN N'空欄の場合、安全なパスワードが自動的に生成されます' END,
    [alumnos_asistente_btn_si]               = CASE [IdiomaID] WHEN 1 THEN N'Sí'                                                          WHEN 2 THEN N'Yes'                                                    WHEN 3 THEN N'Sim'                                                    WHEN 4 THEN N'Oui'                                                      WHEN 5 THEN N'はい' END,
    [alumnos_asistente_btn_no]               = CASE [IdiomaID] WHEN 1 THEN N'No'                                                          WHEN 2 THEN N'No'                                                     WHEN 3 THEN N'Não'                                                    WHEN 4 THEN N'Non'                                                      WHEN 5 THEN N'いいえ' END,
    [alumnos_asistente_btn_buscar]           = CASE [IdiomaID] WHEN 1 THEN N'Buscar'                                                      WHEN 2 THEN N'Search'                                                 WHEN 3 THEN N'Buscar'                                                 WHEN 4 THEN N'Rechercher'                                               WHEN 5 THEN N'検索' END,
    [alumnos_asistente_btn_confirmar]        = CASE [IdiomaID] WHEN 1 THEN N'Confirmar'                                                   WHEN 2 THEN N'Confirm'                                                WHEN 3 THEN N'Confirmar'                                              WHEN 4 THEN N'Confirmer'                                                WHEN 5 THEN N'確認' END,
    [alumnos_credenciales_titulo]            = CASE [IdiomaID] WHEN 1 THEN N'Cuenta creada'                                               WHEN 2 THEN N'Account created'                                        WHEN 3 THEN N'Conta criada'                                           WHEN 4 THEN N'Compte créé'                                              WHEN 5 THEN N'アカウントが作成されました' END,
    [alumnos_credenciales_aviso]             = CASE [IdiomaID] WHEN 1 THEN N'Guardá o entregá estos datos: no se van a volver a mostrar.' WHEN 2 THEN N'Save or hand over these details: they will not be shown again.' WHEN 3 THEN N'Salve ou entregue estes dados: eles não serão exibidos novamente.' WHEN 4 THEN N'Enregistrez ou remettez ces informations : elles ne seront plus affichées.' WHEN 5 THEN N'この情報を保存するか渡してください。二度と表示されません。' END,
    [alumnos_msg_familiar_vinculado]         = CASE [IdiomaID] WHEN 1 THEN N'Familiar vinculado correctamente'                            WHEN 2 THEN N'Family member linked successfully'                      WHEN 3 THEN N'Familiar vinculado com sucesso'                          WHEN 4 THEN N'Membre de la famille lié avec succès'                      WHEN 5 THEN N'家族が正常に関連付けられました' END,
    [alumnos_msg_familiar_desvinculado]      = CASE [IdiomaID] WHEN 1 THEN N'Familiar desvinculado correctamente'                         WHEN 2 THEN N'Family member unlinked successfully'                    WHEN 3 THEN N'Familiar desvinculado com sucesso'                       WHEN 4 THEN N'Membre de la famille dissocié avec succès'                 WHEN 5 THEN N'家族の関連付けが解除されました' END,
    [alumnos_rol_titular]                    = CASE [IdiomaID] WHEN 1 THEN N'Titular'                                                     WHEN 2 THEN N'Account holder'                                         WHEN 3 THEN N'Titular'                                                WHEN 4 THEN N'Titulaire'                                                WHEN 5 THEN N'本人' END,
    [alumnos_rol_familiar]                   = CASE [IdiomaID] WHEN 1 THEN N'Familiar'                                                    WHEN 2 THEN N'Family member'                                          WHEN 3 THEN N'Familiar'                                               WHEN 4 THEN N'Membre de la famille'                                     WHEN 5 THEN N'家族' END,
    [alumnos_lbl_familiares]                 = CASE [IdiomaID] WHEN 1 THEN N'Familiares vinculados'                                       WHEN 2 THEN N'Linked family members'                                  WHEN 3 THEN N'Familiares vinculados'                                   WHEN 4 THEN N'Membres de la famille liés'                                WHEN 5 THEN N'関連付けられた家族' END,
    [alumnos_familiares_vacio]               = CASE [IdiomaID] WHEN 1 THEN N'Sin familiares vinculados'                                   WHEN 2 THEN N'No linked family members'                               WHEN 3 THEN N'Sem familiares vinculados'                               WHEN 4 THEN N'Aucun membre de la famille lié'                            WHEN 5 THEN N'関連付けられた家族はいません' END;
GO
